-- Sample/demo daily sales data. This project deliberately has no real
-- orders/transactions table or POS integration (see the "honest scoping"
-- note at the top of app/[locale]/admin/page.tsx) — Forecasting only shows
-- the real demand-signal heuristic (cart adds + chat mentions). This table
-- is the one deliberate exception: seeded sample numbers so Vera
-- Intelligence (the admin chat insight feature) has something concrete to
-- reason over for event retro/strategy questions ("why did 9.9
-- underperform", "what should we do for 11.11"). Always surfaced in the UI
-- labeled as demo/sample data, never presented as real sales.
CREATE TABLE IF NOT EXISTS demo_sales (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  product_id UUID NOT NULL REFERENCES products(id) ON DELETE CASCADE,
  sale_date DATE NOT NULL,
  units_sold INTEGER NOT NULL,
  revenue NUMERIC NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS idx_demo_sales_date ON demo_sales (sale_date);
CREATE INDEX IF NOT EXISTS idx_demo_sales_product ON demo_sales (product_id, sale_date);

-- Four events telling one coherent story: 8.8 (healthy), 9.9 (the dip —
-- ad_budget was cut vs. 8.8, which is the root cause Vera Intelligence can
-- point to), 10.10 (partial recovery, budget restored), 11.11 (upcoming,
-- status 'rencana', the one a tenant would ask strategy for next).
ON CONFLICT (promo_code) DO NOTHING;

-- Demand-signal alarm correlated with the 9.9 dip, with a logged root
-- cause — exactly the kind of record Vera Intelligence should cite instead
-- of guessing.
SELECT id, 2, -4.8, 'tindak_lanjut', 'Penjualan 9.9 jauh di bawah proyeksi meski diskon dinaikkan — root cause: ad_budget dipotong ~60% dibanding 8.8.', '2026-09-10 09:00:00+07'
FROM products WHERE id = 'a7b3a760-1d74-4edd-9edc-d58c72396901';





